export type BundleComponent =
  | 'car'
  | 'accessories'
  | 'warranty'
  | 'extended_warranty'
  | 'premium_connectivity'
  | 'ditial'
  | 'connectivity'
  | 'additionalCost'
  | 'wallbox';

export const getBundleComponentQuery = (
  component: BundleComponent,
  baseSiteId: string,
) => {
  const componentMapping: {[key in BundleComponent]: string} = {
    car: `SmartCarComponent`,
    accessories: `SmartAccessoriesComponent`,
    warranty: `SmartWarrantyComponent`,
    extended_warranty: `SmartExtendedWarrantyComponent`,
    premium_connectivity: `SmartExtendedConnectivityComponent-Package`,
    ditial: `SmartDigitalComponent`,
    connectivity: `SmartConnectivityComponent`,
    additionalCost: `SmartAdditionalCostComponent`,
    wallbox: `SmartWallboxComponent`,
  };

  return `${componentMapping[component]}_${baseSiteId}`;
};

