import {EventType} from '@smart/analytics';
import {useTranslations} from '@smart/react-utils';
import * as React from 'react';
import {
  TabActive,
  type TabActiveEnum,
} from '../../../../types/tab-active.types';
import type {AppModel} from '../../../bff/app-model/create-app-model';
import type {ProductSearchProduct} from '../../../bff/product-catalogue-model/create-product-catalogue-model';
import type {Model} from '../../../bff/types';
import {useTracking} from '../../hooks/use-tracking';
import {getTrackingPageData} from '../../utils/get-tracking-page-data';
import {ContentTab} from '../content-tab';
import {InfoBar} from '../info-bar';

type PremiumConnectivityTabProps = {
  appModel: AppModel;
  models: Model[];
  premiumConnectivityOffers: ProductSearchProduct[];
  tabActive: TabActiveEnum;
};

export const PremiumConnectivityTab = ({
  appModel,
  models,
  premiumConnectivityOffers,
  tabActive,
}: PremiumConnectivityTabProps) => {
  const {
    premiumConnectivityAemData: {
      premiumConnectivityIntroText,
      premiumConnectivityHelperText,
      premiumConnectivityProviderPath,
    },
    disclaimerReferences: {extendedWarrantyPriceDisclaimerReference},
    translations,
  } = appModel;
  const trackEvent = useTracking();

  const {t} = useTranslations(translations);

  // NOTE: for EWX we always provide price which includes IPT for both B2C and B2B
  const includesIspTax = t(`common.label.tax.includesInsurancePremiumTax`);

  React.useEffect(() => {
    const pageTrackingData = getTrackingPageData({
      name: `catalogue.premium_connectivity`,
      items: premiumConnectivityOffers,
    });
    if (tabActive === TabActive.PREMIUM_CONNECTIVITY) {
      trackEvent(pageTrackingData, EventType.PAGEVIEW);
    }
  }, [premiumConnectivityOffers, tabActive]);

  return (
    <ContentTab
      providerPath={premiumConnectivityProviderPath}
      inclVatLabel={includesIspTax}
      exclVatLabel={includesIspTax}
      items={premiumConnectivityOffers}
      disclaimerReference={extendedWarrantyPriceDisclaimerReference}
      tabActive={tabActive}
      models={models}
    >
      <InfoBar
        mainText={premiumConnectivityIntroText}
        additionalText={premiumConnectivityHelperText}
      />
    </ContentTab>
  );
};

